-- DEAL: Supabase schema (Section 6 data model + 12.5 API).
-- ALL money columns are bigint integer cents (3460000 = $34,600.00).
-- IDs are text and generated by the backend (e.g. "ses_…", "evt_…") so the in-memory and Supabase stores match.
-- Writes happen ONLY through the backend (service-role key, bypasses RLS).
-- The iOS app uses the anon key for Realtime + SELECT only.
-- Idempotent: safe to run more than once in the Supabase SQL editor.

-- ---------------------------------------------------------------- sessions
create table if not exists public.sessions (
  id               text primary key,
  category         text        not null,
  item             text        not null,                        -- '' until detected (auto sessions)
  asking_price     bigint      check (asking_price >= 0),       -- null = unknown (auto session)
  target_price     bigint      check (target_price >= 0),       -- null = buyer set none
  max_budget       bigint      check (max_budget >= 0),         -- null = buyer set none
  style            text        not null default 'firm',
  status           text        not null default 'live'
                     check (status in ('live', 'agreement_draft', 'locked', 'paid', 'ended')),
  join_code        text        not null,
  -- additions beyond Section 6 (live dashboard state):
  current_offer    bigint,
  current_offer_by text check (current_offer_by in ('buyer', 'seller')),
  terms            jsonb       not null default '[]'::jsonb,   -- Term[] (B3 "Terms so far", PATCH /terms)
  listing          jsonb,                                       -- Listing from POST /listings/parse (marketplace)
  condition_checks jsonb       not null default '[]'::jsonb,   -- ConditionCheck[] from POST /sessions/:id/condition-check
  auto             boolean     not null default false,          -- "Start listening" session (item detected from speech)
  detected         boolean     not null default true,           -- false until an auto session's item is known
  ended_at         timestamptz,                                 -- POST /sessions/:id/end
  summary          jsonb,                                       -- SessionSummary {outcome, final_price, headline, key_points}
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists sessions_join_code_idx on public.sessions (join_code);
create index if not exists sessions_created_at_idx on public.sessions (created_at desc);

-- ---------------------------------------------------------------- events
create table if not exists public.events (
  id               text primary key,
  session_id       text        not null references public.sessions (id) on delete cascade,
  seq              integer     not null,                      -- order within the session
  speaker          text        not null check (speaker in ('buyer', 'seller')),
  text             text        not null,
  "timestamp"      timestamptz not null default now(),
  extracted_offer  bigint,                                    -- standing offer after this line (cents)
  offer_by         text check (offer_by in ('buyer', 'seller')),
  new_terms        jsonb       not null default '[]'::jsonb,  -- [{type,label,amount}]
  tactic           text,
  cue              text,
  cue_detail       text,                                      -- second glasses line, e.g. "$489/mo × 72 = $35,208"
  status_color     text        not null default 'yellow' check (status_color in ('green', 'yellow', 'red')),
  script_line_id   text,                                      -- "evt_01" when inserted by /script/play
  kind             text        not null default 'speech' check (kind in ('speech', 'condition_check')),
  unique (session_id, seq)
);
-- Marketplace additions, for databases created before them (no-ops on a fresh run).
alter table public.sessions add column if not exists listing jsonb;
alter table public.sessions add column if not exists condition_checks jsonb not null default '[]'::jsonb;
alter table public.events   add column if not exists kind text not null default 'speech';

-- Auto ("Start listening") sessions, for databases created before them (no-ops on a fresh run).
alter table public.sessions add column if not exists auto     boolean not null default false;
alter table public.sessions add column if not exists detected boolean not null default true;
alter table public.sessions add column if not exists ended_at timestamptz;
alter table public.sessions add column if not exists summary  jsonb;
alter table public.sessions alter column asking_price drop not null;
alter table public.sessions alter column target_price drop not null;
alter table public.sessions alter column max_budget   drop not null;
alter table public.sessions drop constraint if exists sessions_status_check;
alter table public.sessions add constraint sessions_status_check
  check (status in ('live', 'agreement_draft', 'locked', 'paid', 'ended'));

create index if not exists events_session_idx on public.events (session_id, seq);

-- ---------------------------------------------------------------- agreements
create table if not exists public.agreements (
  id                  text primary key,
  session_id          text        not null references public.sessions (id) on delete cascade,
  price               bigint      not null,
  items               jsonb       not null default '[]'::jsonb,  -- string[]; items[0] = session item
  fees                jsonb       not null default '[]'::jsonb,  -- [{label, amount, note?}]
  total               bigint      not null,
  source_event_ids    jsonb       not null default '[]'::jsonb,  -- string[] of events.id
  open_questions      jsonb       not null default '[]'::jsonb,  -- string[]
  status              text        not null default 'draft' check (status in ('draft', 'locked')),
  buyer_confirmed_at  timestamptz,
  seller_confirmed_at timestamptz,
  fingerprint         text,                                      -- SHA-256 hex, set when both confirmed
  version             integer     not null default 1,            -- bumps when the buyer approves a changed charge
  amendments          jsonb       not null default '[]'::jsonb,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index if not exists agreements_session_idx on public.agreements (session_id, created_at desc);

-- ---------------------------------------------------------------- payment_requests
create table if not exists public.payment_requests (
  id                   text primary key,
  session_id           text        not null references public.sessions (id) on delete cascade,
  agreement_id         text        not null references public.agreements (id) on delete cascade,
  amount               bigint      not null,                     -- sum of line_items
  line_items           jsonb       not null default '[]'::jsonb, -- [{label, amount}]
  status               text        not null default 'pending'
                         check (status in ('pending', 'blocked', 'approved', 'rejected', 'paid')),
  mismatch_explanation text,
  mismatch             jsonb,                                    -- structured MismatchDetails (B5 side-by-side)
  decided_at           timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
create index if not exists payment_requests_session_idx on public.payment_requests (session_id, created_at);

-- ---------------------------------------------------------------- receipts
create table if not exists public.receipts (
  id                    text primary key,
  session_id            text        not null references public.sessions (id) on delete cascade,
  payment_request_id    text        not null references public.payment_requests (id) on delete cascade,
  stripe_payment_id     text        not null,
  amount                bigint      not null,
  currency              text        not null default 'usd',
  status                text        not null,
  agreement_fingerprint text        not null,
  merchant              text        not null default 'DEAL Demo Seller',
  asking_price          bigint      not null default 0,
  blocked_total         bigint      not null default 0,
  summary               text        not null default '',
  mock                  boolean     not null default false,
  created_at            timestamptz not null default now()
);
create index if not exists receipts_session_idx on public.receipts (session_id, created_at desc);

-- ---------------------------------------------------------------- Realtime
-- Full row images so UPDATE events carry every column to the phones.
alter table public.sessions         replica identity full;
alter table public.events           replica identity full;
alter table public.agreements       replica identity full;
alter table public.payment_requests replica identity full;
alter table public.receipts         replica identity full;

do $$
declare t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  foreach t in array array['sessions', 'events', 'agreements', 'payment_requests', 'receipts'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------- RLS
-- Hackathon tradeoff (12.4): anon may SELECT (needed for Realtime); no anon writes.
-- The backend's service-role key bypasses RLS for all writes.
do $$
declare t text;
begin
  foreach t in array array['sessions', 'events', 'agreements', 'payment_requests', 'receipts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "anon read %s" on public.%I', t, t);
    execute format('create policy "anon read %s" on public.%I for select to anon, authenticated using (true)', t, t);
  end loop;
end $$;

grant usage on schema public to anon, authenticated;
grant select on public.sessions, public.events, public.agreements, public.payment_requests, public.receipts to anon, authenticated;
revoke insert, update, delete on public.sessions, public.events, public.agreements, public.payment_requests, public.receipts from anon, authenticated;
